css:
/* Force any table rendered inside text fields to take full page width */
.print-format table {
    width: 100% !important;
    table-layout: fixed !important;
    border-collapse: collapse !important;
}

/* Ensure individual columns wrap text cleanly instead of breaking constraints */
.print-format td, .print-format th {
    word-wrap: break-word !important;
    word-break: break-all !important;
    white-space: normal !important;
}

html:
{% if doc and doc.company %}
    {# 1. Fetch Company details dynamically from the active document #}
    {% set co_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
    {% set co_phone = frappe.db.get_value("Company", doc.company, "phone_no") %}
    {% set co_email = frappe.db.get_value("Company", doc.company, "email") %}
    {% set co_web = frappe.db.get_value("Company", doc.company, "website") %}
    {% set co_tax = frappe.db.get_value("Company", doc.company, "tax_id") %}
    {% set co_reg = frappe.db.get_value("Company", doc.company, "registration_details") %}

    <div class="letter-head-container" style="font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; color: #333333; width: 100%; border-bottom: 2px solid #1B365D; padding-top: 0px; margin-bottom: 0px; text-align: center;">

        <!-- Line 1: Logo Top Center -->
        <div class="logo-wrapper" style="display: block; margin-bottom: 1px; width: 100%; text-align: center;">
            {% if co_logo %}
                <img src="{{ co_logo }}" alt="{{ doc.company }}" style="max-height: 70px; max-width: 350px; width: auto; object-fit: contain; margin: 0 auto; display: block;">
            {% else %}
                <h1 style="margin: 0 0 2px 0; font-size: 20px; font-weight: 700; color: #1B365D; letter-spacing: -0.5px;">{{ doc.company }}</h1>
            {% endif %}
        </div>

        <!-- Lines 2 to 4: Company Details Below Logo -->
        <div class="company-details" style="font-size: 10px; line-height: 1.3; color: #555555; width: 100%; text-align: center; margin: 0; padding: 0;">
            <!--<div style="font-weight: bold; font-size: 11px; color: #1B365D; margin-bottom: 1px;">{{ doc.company }}</div>-->
            <div>
                Registration Number: {{co_reg or '2018/262050/07'}}<br>
                {% if co_tax %}Vat Registration Number: {{ co_tax }} &nbsp;&bull;&nbsp;{% endif %}<br>
                Address:{{co_address or 'Corner Jurgens and Pretoria Street, Jetpark ◘ 446 Skilder Street, Silverton, Pretoria 0127 ◘ PO Box 444, Pretoria 0001'}}<br>
                Phone: {{ co_phone or '' }} &nbsp;&bull;&nbsp; 
                Call Centre: 087 980 5196 &nbsp;&bull;&nbsp;
                Mobile: 082 975 1221<br>
                Email: workshop@ukulungiswa.com &nbsp;&bull;&nbsp;callcentre@ukulungiswa.com &nbsp;&bull;&nbsp; info@ukulungiswa.com

            </div>

        </div>

        <!-- Separator -->
        <div style="border-bottom: 1px solid #E2E8F0; margin-top: 8px; margin-bottom: 1px; width: 100%;"></div>
    </div>
{% else %}
    <!-- Fallback if letter head is previewed outside of a document transaction context -->
    <div style="text-align: center; font-family: sans-serif; font-size: 12px; color: #777;">
        [Dynamic Company Letterhead Preview]
    </div>
{% endif %}
